/// <summary>
/// PricingAttribute of table <c>LogisticsPostalAddress</c> field City.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeLogisticsPostalAddressCity extends UPSPricingAttributeLogisticsPostalAddress implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(LogisticsPostalAddress, City);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    LogisticsPostalAddress logisticsPostalAddress;

    while select logisticsPostalAddress
        group by City
    {
        if (! ret.in(logisticsPostalAddress.City))
        {
            ret.add(logisticsPostalAddress.City);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(LogisticsPostalAddress, City));
    qbr.value(queryValue(_value));
}
